#!/usr/bin/env python3
"""
AI Impact on the Global Job Market: Trend Analysis Report Generator
Produces a self-contained HTML report with embedded Chart.js visualizations.
"""

import pandas as pd
import numpy as np
import json
from datetime import datetime

# ---------------------------------------------------------------------------
# 1. Load & Prepare Data
# ---------------------------------------------------------------------------
df = pd.read_csv("/app/benchmark/data.csv")

YEARS = sorted(df["year"].unique())
YEAR_LABELS = [str(y) for y in YEARS]
COUNTRIES = sorted(df["country"].unique())
JOB_TITLES = sorted(df["job_title"].unique())
EXP_LEVELS = ["Entry", "Mid", "Senior"]
EDU_LEVELS = ["Bachelor", "Master", "PhD"]
SKILLS = sorted(df["primary_skill"].unique())

# ---------------------------------------------------------------------------
# 2. KPI Calculations
# ---------------------------------------------------------------------------

# ---- Global KPIs ----
global_avg_risk = round(df["ai_risk_score"].mean(), 3)
global_median_salary = round(df["salary"].median(), 0)
total_records = len(df)
survival_rate = round((df["job_survival_class"] >= 1).mean() * 100, 1)
avg_skill_demand = round(df["skill_demand_score"].mean(), 1)
total_openings = int(df["job_openings"].sum())

# ---- Year-over-year KPIs ----
yearly = df.groupby("year").agg(
    avg_risk=("ai_risk_score", "mean"),
    median_salary=("salary", "median"),
    mean_salary=("salary", "mean"),
    survival_rate=("job_survival_class", lambda x: (x >= 1).mean() * 100),
    avg_skill_demand=("skill_demand_score", "mean"),
    total_openings=("job_openings", "sum"),
    count=("year", "size"),
).reset_index()

# ---- By Job Title ----
by_job = df.groupby("job_title").agg(
    avg_risk=("ai_risk_score", "mean"),
    median_salary=("salary", "median"),
    survival_rate=("job_survival_class", lambda x: (x >= 1).mean() * 100),
    avg_skill_demand=("skill_demand_score", "mean"),
    total_openings=("job_openings", "sum"),
    count=("job_title", "size"),
).reset_index().sort_values("avg_risk", ascending=False)

# ---- By Country ----
by_country = df.groupby("country").agg(
    avg_risk=("ai_risk_score", "mean"),
    median_salary=("salary", "median"),
    survival_rate=("job_survival_class", lambda x: (x >= 1).mean() * 100),
    total_openings=("job_openings", "sum"),
    count=("country", "size"),
).reset_index().sort_values("median_salary", ascending=False)

# ---- By Experience Level ----
by_exp = df.groupby("experience_level").agg(
    avg_risk=("ai_risk_score", "mean"),
    median_salary=("salary", "median"),
    survival_rate=("job_survival_class", lambda x: (x >= 1).mean() * 100),
).reset_index()

# ---- By Education Level ----
by_edu = df.groupby("education_level").agg(
    avg_risk=("ai_risk_score", "mean"),
    median_salary=("salary", "median"),
    survival_rate=("job_survival_class", lambda x: (x >= 1).mean() * 100),
).reset_index()

# ---- Risk Category Distribution ----
risk_cat_counts = df["ai_risk_category"].value_counts().to_dict()

# ---- Salary Bucket Distribution ----
salary_bucket_counts = df["salary_bucket"].value_counts().to_dict()

# ---- Survival Class Distribution ----
surv_class_counts = df["job_survival_class"].value_counts().sort_index().to_dict()

# ---- Year x Job Title: avg risk ----
year_job_risk = df.groupby(["year", "job_title"])["ai_risk_score"].mean().unstack().fillna(0)

# ---- Year x Country: median salary ----
year_country_salary = df.groupby(["year", "country"])["salary"].median().unstack().fillna(0)

# ---- Year x Job Title: median salary ----
year_job_salary = df.groupby(["year", "job_title"])["salary"].median().unstack().fillna(0)

# ---- Year x Experience: median salary ----
year_exp_salary = df.groupby(["year", "experience_level"])["salary"].median().unstack().fillna(0)

# ---- Year x Skill: avg demand ----
year_skill_demand = df.groupby(["year", "primary_skill"])["skill_demand_score"].mean().unstack().fillna(0)

# ---- Year x Job: total openings ----
year_job_openings = df.groupby(["year", "job_title"])["job_openings"].sum().unstack().fillna(0)

# ---- Salary vs AI Risk correlation ----
salary_risk_corr = round(df["salary"].corr(df["ai_risk_score"]), 4)

# ---- Salary by risk category ----
salary_by_risk_cat = df.groupby("ai_risk_category")["salary"].agg(["median", "mean", "count"]).reset_index()

# ---- Year x Risk Category: count proportions ----
year_risk_cat = df.groupby(["year", "ai_risk_category"]).size().unstack(fill_value=0)
year_risk_cat_pct = year_risk_cat.div(year_risk_cat.sum(axis=1), axis=0) * 100

# ---- Year: survival rate by job title ----
year_job_survival = df.groupby(["year", "job_title"])["job_survival_class"].apply(
    lambda x: (x >= 1).mean() * 100
).unstack().fillna(0)

# ---- Skill x Survival ----
skill_survival = df.groupby("primary_skill").agg(
    avg_demand=("skill_demand_score", "mean"),
    survival_rate=("job_survival_class", lambda x: (x >= 1).mean() * 100),
    avg_risk=("ai_risk_score", "mean"),
    count=("primary_skill", "size"),
).reset_index().sort_values("survival_rate", ascending=False)

# ---- Country x Job Title: avg risk heatmap data ----
country_job_risk = df.groupby(["country", "job_title"])["ai_risk_score"].mean().unstack().fillna(0)

# ---- Experience x Job Title: survival rate ----
